"use client";

import * as Primitive from "@radix-ui/react-dropdown-menu";
import { Check, Circle } from "lucide-react";
import { useEffect, useRef, useState, type ComponentProps, type ReactNode } from "react";
import { GlideHighlight, useHighlightedGlide } from "./glide-highlight";
import { cn } from "./lib/cn";
import "./shared/dropdown-content.css";
import "./dropdown-menu.css";

export const DropdownMenu = Primitive.Root;
export const DropdownMenuTrigger = Primitive.Trigger;
export const DropdownMenuGroup = Primitive.Group;
export const DropdownMenuRadioGroup = Primitive.RadioGroup;

export function DropdownMenuContent({
  className,
  sideOffset = 8,
  collisionPadding = 16,
  children,
  ...props
}: ComponentProps<typeof Primitive.Content>) {
  const [content, setContent] = useState<HTMLDivElement | null>(null);
  const box = useHighlightedGlide(content);
  return (
    <Primitive.Portal>
      <Primitive.Content
        ref={setContent}
        data-slot="dropdown-content"
        sideOffset={sideOffset}
        collisionPadding={collisionPadding}
        className={cn(
          "relative z-50 min-w-56 max-w-[calc(100vw-2rem)] max-h-[var(--radix-dropdown-menu-content-available-height)] overflow-y-auto rounded-surface border border-border bg-elevated p-1 text-[13px] text-foreground shadow-overlay outline-none",
          className,
        )}
        {...props}
      >
        <GlideHighlight box={box} />
        {children}
      </Primitive.Content>
    </Primitive.Portal>
  );
}

/** Row anatomy shared by every menu: dropdown, menubar and context menus. */
export const menuItemClass =
  "relative z-10 flex min-h-[34px] max-md:min-h-[var(--control-height)] cursor-default select-none items-center gap-2.5 rounded-control px-2.5 text-[13px] font-normal outline-none data-[highlighted]:text-foreground data-[disabled]:pointer-events-none data-[disabled]:opacity-45 data-[variant=destructive]:text-destructive [&_svg]:size-4 [&_svg]:shrink-0 [&_svg]:text-muted-foreground data-[variant=destructive]:[&_svg]:text-destructive";

export function DropdownMenuItem({
  className,
  ...props
}: ComponentProps<typeof Primitive.Item>) {
  return (
    <Primitive.Item
      data-slot="dropdown-item"
      className={cn(menuItemClass, className)}
      {...props}
    />
  );
}
export function DropdownMenuCheckboxItem({
  className,
  children,
  ...props
}: ComponentProps<typeof Primitive.CheckboxItem>) {
  return (
    <Primitive.CheckboxItem
      data-slot="dropdown-item"
      className={cn(menuItemClass, "pl-8", className)}
      {...props}
    >
      <span className="absolute left-2.5 flex size-4 items-center justify-center">
        <Primitive.ItemIndicator>
          <Check aria-hidden="true" />
        </Primitive.ItemIndicator>
      </span>
      {children}
    </Primitive.CheckboxItem>
  );
}
export function DropdownMenuRadioItem({
  className,
  children,
  ...props
}: ComponentProps<typeof Primitive.RadioItem>) {
  return (
    <Primitive.RadioItem
      data-slot="dropdown-item"
      className={cn(menuItemClass, "pl-8", className)}
      {...props}
    >
      <span className="absolute left-2.5 flex size-4 items-center justify-center">
        <Primitive.ItemIndicator>
          <Circle className="!size-2 fill-current" aria-hidden="true" />
        </Primitive.ItemIndicator>
      </span>
      {children}
    </Primitive.RadioItem>
  );
}
export function DropdownMenuLabel({
  className,
  ...props
}: ComponentProps<typeof Primitive.Label>) {
  return (
    <Primitive.Label
      className={cn(
        "px-2.5 pb-1 pt-2 text-xs font-medium text-muted-foreground",
        className,
      )}
      {...props}
    />
  );
}
export function DropdownMenuSeparator({
  className,
  ...props
}: ComponentProps<typeof Primitive.Separator>) {
  return (
    <Primitive.Separator
      className={cn("-mx-1 my-1 h-px bg-border", className)}
      {...props}
    />
  );
}

export function DropdownMenuShortcut({
  className,
  ...props
}: ComponentProps<"span">) {
  return (
    <span
      className={cn(
        "ml-auto pl-4 font-mono text-xs tracking-wide text-muted-foreground",
        className,
      )}
      {...props}
    />
  );
}

/**
 * A destructive item that asks in place: choosing it turns the row into the
 * question with Cancel and the confirming action, instead of stacking a
 * dialog on the menu. Both answers are menu items, so arrows and Enter work.
 */
export function DropdownMenuConfirmItem({
  label,
  icon,
  question,
  detail,
  confirmLabel = "Delete",
  onConfirm,
}: {
  label: string;
  icon?: ReactNode;
  /** e.g. "Delete 3 files?" */
  question: string;
  /** e.g. "They move to Trash for 30 days." */
  detail?: string;
  confirmLabel?: string;
  onConfirm: () => void;
}) {
  const [asking, setAsking] = useState(false);
  const cancel = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (asking) cancel.current?.focus();
  }, [asking]);
  if (!asking) {
    return (
      <DropdownMenuItem
        data-variant="destructive"
        onSelect={(event) => {
          event.preventDefault();
          setAsking(true);
        }}
      >
        {icon}
        {label}
      </DropdownMenuItem>
    );
  }
  return (
    <div data-slot="menu-confirm" role="group" aria-label={question}>
      <p className="px-2.5 pt-2 text-[13px] font-medium text-destructive">{question}</p>
      {detail && <p className="px-2.5 pb-1 text-xs text-muted-foreground">{detail}</p>}
      <DropdownMenuItem
        ref={cancel}
        onSelect={(event) => {
          event.preventDefault();
          setAsking(false);
        }}
      >
        Cancel
      </DropdownMenuItem>
      <DropdownMenuItem data-variant="destructive" onSelect={onConfirm}>
        {icon}
        {confirmLabel}
      </DropdownMenuItem>
    </div>
  );
}

"use client";

import { useLayoutEffect, useState } from "react";
import "./glide-highlight.css";

export type GlideBox = {
  active: boolean;
  left: number;
  top: number;
  width: number;
  height: number;
};

export function glideBox(target: HTMLElement): GlideBox {
  return {
    active: true,
    left: target.offsetLeft,
    top: target.offsetTop,
    width: target.offsetWidth,
    height: target.offsetHeight,
  };
}

export function useHighlightedGlide(
  root: HTMLElement | null,
  selector = "[data-highlighted]",
  /** Attributes whose change can move the target, e.g. data-state for an open trigger. */
  attributes: readonly string[] = ["data-highlighted"],
) {
  const [box, setBox] = useState<GlideBox | null>(null);

  useLayoutEffect(() => {
    const element = root;
    if (!element) return;
    const update = () => {
      const target = element.querySelector<HTMLElement>(selector);
      setBox((current) =>
        target ? glideBox(target) : current ? { ...current, active: false } : null,
      );
    };
    update();
    const observer = new MutationObserver(update);
    observer.observe(element, {
      subtree: true,
      attributes: true,
      attributeFilter: [...attributes],
    });
    return () => observer.disconnect();
    // The attribute list is fixed per call site.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [root, selector]);

  return box;
}

export function GlideHighlight({ box }: { box: GlideBox | null }) {
  if (!box) return null;
  return (
    <span
      aria-hidden="true"
      data-slot="glide-highlight"
      data-active={box.active}
      style={{
        width: box.width,
        height: box.height,
        transform: `translate(${box.left}px, ${box.top}px)`,
      }}
    />
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/* Shared by context-menu.tsx, dropdown-menu.tsx; each imports it. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="dropdown-item"] {
    transition:
      color var(--duration-fast) var(--ease-out),
      background-color var(--duration-fast) var(--ease-out),
      scale var(--duration-fast) var(--ease-out);
  }
  [data-slot="dropdown-item"]:focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: -2px;
  }
  [data-slot="dropdown-content"] {
    transform-origin: var(--radix-dropdown-menu-content-transform-origin);
  }
  [data-slot="dropdown-content"] [data-slot="glide-highlight"] {
    border-radius: var(--radius-control);
    transition:
      transform var(--duration-fast) var(--ease-out),
      width var(--duration-fast) var(--ease-out),
      height var(--duration-fast) var(--ease-out),
      opacity var(--duration-fast) var(--ease-out);
  }
  [data-slot="dropdown-content"][data-state="open"] {
    animation: caliper-dialog-enter var(--duration-normal) var(--ease-settle);
  }
  [data-slot="dropdown-content"][data-state="closed"] {
    animation: caliper-fade-out var(--duration-fast) var(--ease-in) forwards;
    pointer-events: none;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="dropdown-item"] {
      transition: none;
    }
    [data-slot="dropdown-content"] {
      animation: none;
    }
    /* Preserve the exit name for Radix Presence's completion matcher, including
       a preference changed during exit. No visual motion or unmount timer. */
    [data-slot="dropdown-content"][data-state="closed"] {
      animation: caliper-fade-out var(--duration-instant) var(--ease-in) forwards !important;
    }
  }
}

[data-slot="dropdown-content"] {
  background-color: var(--elevated-glass);
  border-color: color-mix(in srgb, var(--edge-light) 45%, var(--border));
  backdrop-filter: blur(var(--blur-overlay));
  box-shadow:
    var(--shadow-overlay),
    0 0 40px var(--edge-glow),
    inset 0 1px 0 var(--edge-light);
}
@layer components {
  [data-slot="dropdown-content"][data-variant="glass"] {
    background: var(--elevated-glass);
    -webkit-backdrop-filter: blur(24px) saturate(1.5);
    backdrop-filter: blur(24px) saturate(1.5);
    border-color: color-mix(in srgb, var(--edge-light) 45%, var(--border));
    box-shadow: var(--shadow-overlay), inset 0 1px 0 var(--edge-light);
    border-radius: 20px;
  }
  /* Moving along the bar swaps menus at once: a closing menu that lingered to fade would see focus leave and dismiss the bar. */
  [data-slot="dropdown-content"][data-menubar][data-state="closed"] { animation: none; }
}

/* dropdown-menu.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="menu-confirm"] {
    margin: 2px 0;
    padding-bottom: 2px;
    border-radius: var(--radius-control);
    background: var(--destructive-subtle);
    animation: caliper-fade-in var(--duration-fast) var(--ease-out);
  }
}

/* glide-highlight.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="glide-highlight"] {
    position: absolute;
    top: 0;
    left: 0;
    z-index: 0;
    pointer-events: none;
    border-radius: var(--radius-surface);
    background: var(--muted);
    opacity: 0;
    transition:
      transform var(--duration-travel) var(--ease-showcase),
      width var(--duration-travel) var(--ease-showcase),
      height var(--duration-travel) var(--ease-showcase),
      opacity var(--duration-deliberate) var(--ease-out);
  }
  [data-slot="glide-highlight"][data-active="true"] {
    opacity: 1;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="glide-highlight"] {
      transition: none;
    }
    [data-slot="glide-highlight"] {
      transition:
        transform 400ms var(--ease-showcase),
        width 400ms var(--ease-showcase),
        height 400ms var(--ease-showcase),
        opacity 280ms var(--ease-out);
    }
  }
}
